// <auto-generated companion /> — mirrors C++ <c>Spark::WorldQuery</c> on <c>GameWorld</c>.
#nullable enable

using System.Collections.Generic;

namespace Spark.Bindings;

/// <summary>Batched object queries (tags, names, component kinds, full filters).</summary>
public sealed class GameObjectQuery
{
    private readonly GameWorld _world;

    public GameObjectQuery(GameWorld world) => _world = world;

    public GameObject? FindWithTag(string tag, bool includeInactive = false) =>
        _world.Entities.FindWithTag(tag, includeInactive);

    public GameObject? FindByName(string name, bool includeInactive = false) =>
        _world.Entities.FindByName(name, includeInactive);

    /// <summary>Returns total matches; fills <paramref name="buffer"/> up to its length.</summary>
    public int CollectWithTag(string tag, Span<GameObject> buffer, bool includeInactive = false) =>
        Collect(GameObjectQueryFilter.WithTag(tag, includeInactive), buffer);

    public int CollectWithComponent(
        SparkComponentKind kind,
        Span<GameObject> buffer,
        bool includeInactive = false) =>
        Collect(GameObjectQueryFilter.WithComponent(kind, includeInactive), buffer);

    /// <summary>Count-only when <paramref name="buffer"/> is empty.</summary>
    public int CountMatches(GameObjectQueryFilter filter) => Collect(filter, Span<GameObject>.Empty);

    public unsafe int Collect(GameObjectQueryFilter filter, Span<GameObject> buffer)
    {
        if (buffer.IsEmpty)
        {
            return CollectFiltered(filter, null, 0);
        }

        var nativeBuffer = stackalloc SparkGameObject*[buffer.Length];
        int total = CollectFiltered(filter, nativeBuffer, (uint)buffer.Length);
        int copy = System.Math.Min(total, buffer.Length);
        for (int i = 0; i < copy; i++)
        {
            buffer[i] = new GameObject(InteropPtr.From(nativeBuffer[i]));
        }

        return total;
    }

    public GameObject[] Query(GameObjectQueryFilter filter)
    {
        int total = CountMatches(filter);
        if (total <= 0)
        {
            return [];
        }

        var results = new GameObject[total];
        Collect(filter, results);
        return results;
    }

    public void CollectInto(List<GameObject> destination, GameObjectQueryFilter filter)
    {
        int total = CountMatches(filter);
        if (total <= 0)
        {
            return;
        }

        var scratch = new GameObject[total];
        Collect(filter, scratch);
        destination.EnsureCapacity(destination.Count + total);
        foreach (GameObject obj in scratch)
        {
            destination.Add(obj);
        }
    }

    public void CollectFresh(List<GameObject> destination, GameObjectQueryFilter filter)
    {
        destination.Clear();
        CollectInto(destination, filter);
    }

    private unsafe int CollectFiltered(
        GameObjectQueryFilter filter,
        SparkGameObject** outObjects,
        uint capacity)
    {
        int total = 0;
        if (filter.TagEquals == null)
        {
            var native = filter.ToNative(IntPtr.Zero);
            total = (int)Native.spark_world_query_collect_filtered(
                InteropPtr.World(_world.Handle),
                &native,
                outObjects,
                capacity);
        }
        else
        {
            InteropUtf8.WithUtf8(filter.TagEquals, tagPtr =>
            {
                var native = filter.ToNative(tagPtr);
                total = (int)Native.spark_world_query_collect_filtered(
                    InteropPtr.World(_world.Handle),
                    &native,
                    outObjects,
                    capacity);
            });
        }

        return total;
    }
}
